import { useState, useEffect } from "react"
import api from "../api/client"
import { Activity, ArrowDownCircle, ArrowUpCircle, PlusCircle, Trash, TrendingDown, TrendingUp, Wallet } from "lucide-react"

export default function TransactionsPage() {

  const [transactions, setTransactions] = useState([])
  const [categories, setCategories] = useState([])
  const [loading, setLoading] = useState(false)

  // Champs du formulaire — calqués sur votre modèle Transaction
  const [form, setForm] = useState({
    type: "entree",
    description: "",
    montant: "",
    categorie: "",
    date: new Date().toISOString().split("T")[0],
    statut: "confirme",
  })

  // ── Chargement des transactions ──────────────────────
  const getTransactions = async () => {
    try {
      const res = await api.get("transactions/")
      setTransactions(res.data)
    } catch (error) {
      console.error("Erreur chargement transactions", error)
    }
  }

  // ── Chargement des catégories ────────────────────────
  const getCategories = async () => {
    try {
      const res = await api.get("categories/")
      setCategories(res.data)
    } catch (error) {
      console.error("Erreur chargement catégories", error)
    }
  }

  // ── Supprimer une transaction ────────────────────────
  const deleteTransaction = async (id) => {
    try {
      await api.delete(`transactions/${id}/`)
      getTransactions()
    } catch (error) {
      console.error("Erreur suppression transaction", error)
    }
  }

  // ── Ajouter une transaction ──────────────────────────
  const addTransaction = async () => {
    if (!form.description || !form.montant || !form.date) {
      alert("Merci de remplir tous les champs obligatoires")
      return
    }

    setLoading(true)
    try {
      await api.post("transactions/", {
        type: form.type,
        description: form.description,
        montant: Number(form.montant),
        categorie: form.categorie || null,
        date: form.date,
        statut: form.statut,
      })
      getTransactions()
      // Fermer le modal
      const modal = document.getElementById("modal_transaction")
      if (modal) modal.close()
      // Réinitialiser le formulaire
      setForm({
        type: "entree",
        description: "",
        montant: "",
        categorie: "",
        date: new Date().toISOString().split("T")[0],
        statut: "confirme",
      })
    } catch (error) {
      console.error("Erreur ajout transaction", error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    getTransactions()
    getCategories()
  }, [])

  // ── Calculs solde / revenus / dépenses ───────────────
  // Basé sur le champ "type" de votre modèle ('entree' ou 'sortie')
  const totalEntrees = transactions
    .filter((t) => t.type === "entree" && t.statut === "confirme")
    .reduce((acc, t) => acc + Number(t.montant), 0)

  const totalSorties = transactions
    .filter((t) => t.type === "sortie" && t.statut === "confirme")
    .reduce((acc, t) => acc + Number(t.montant), 0)

  const solde = totalEntrees - totalSorties

  const ratio = totalEntrees > 0
    ? Math.min((totalSorties / totalEntrees) * 100, 100)
    : 0

  // ── Filtrer catégories selon le type choisi ──────────
  const categoriesFiltrees = categories.filter((c) => c.type === form.type)

  // ── Formater la date ─────────────────────────────────
  const formatDate = (dateString) => {
    const d = new Date(dateString)
    return d.toLocaleDateString("fr-FR", {
      year: "numeric",
      month: "short",
      day: "numeric",
    })
  }

  // ── Badge statut ─────────────────────────────────────
  const badgeStatut = (statut) => {
    if (statut === "confirme") return "badge badge-success badge-soft"
    if (statut === "en_attente") return "badge badge-warning badge-soft"
    return "badge badge-error badge-soft"
  }

  const labelStatut = (statut) => {
    if (statut === "confirme") return "Confirmé"
    if (statut === "en_attente") return "En attente"
    return "Annulée"
  }

  return (
    <div className="w-2/3 flex flex-col gap-4">

      {/* ── Cartes solde / revenus / dépenses ── */}
      <div className="flex justify-between rounded-2xl border-2 border-warning/10
        border-dashed bg-warning/5 p-5">

        <div className="flex flex-col gap-1">
          <div className="badge badge-soft">
            <Wallet className="w-4 h-4" />
            Solde
          </div>
          <div className={`stat-value ${solde >= 0 ? "text-success" : "text-error"}`}>
            {solde.toFixed(2)} FCFA
          </div>
        </div>

        <div className="flex flex-col gap-1">
          <div className="badge badge-soft badge-success">
            <ArrowUpCircle className="w-4 h-4" />
            Revenus
          </div>
          <div className="stat-value text-success">
            +{totalEntrees.toFixed(2)} FCFA
          </div>
        </div>

        <div className="flex flex-col gap-1">
          <div className="badge badge-soft badge-error">
            <ArrowDownCircle className="w-4 h-4" />
            Dépenses
          </div>
          <div className="stat-value text-error">
            -{totalSorties.toFixed(2)} FCFA
          </div>
        </div>
      </div>

      {/* ── Barre de progression dépenses vs revenus ── */}
      <div className="rounded-2xl border-2 border-warning/10 border-dashed bg-warning/5 p-5">
        <div className="flex justify-between items-center mb-1">
          <div className="badge badge-soft badge-warning gap-1">
            <Activity className="w-4 h-4" />
            Dépenses vs Revenus
          </div>
          <div>{ratio.toFixed(0)}%</div>
        </div>
        <progress
          className="progress progress-warning w-full"
          value={ratio}
          max={100}
        />
      </div>

      {/* ── Bouton ajouter ── */}
      <button
        className="btn btn-warning"
        onClick={() =>
          document.getElementById("modal_transaction").showModal()
        }
      >
        <PlusCircle className="w-4 h-4" />
        Ajouter une transaction
      </button>

      {/* ── Tableau des transactions ── */}
      <div className="overflow-x-auto rounded-2xl border-2 border-warning/10 border-dashed bg-warning/5">
        <table className="table">
          <thead>
            <tr>
              <th>#</th>
              <th>Description</th>
              <th>Catégorie</th>
              <th>Montant</th>
              <th>Date</th>
              <th>Statut</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {transactions.length === 0 && (
              <tr>
                <td colSpan={7} className="text-center text-base-content/50 py-8">
                  Aucune transaction trouvée
                </td>
              </tr>
            )}
            {transactions.map((t, index) => (
              <tr key={t.id}>
                <th>{index + 1}</th>
                <td>{t.description}</td>
                <td>
                  {t.categorie_detail
                    ? t.categorie_detail.nom
                    : <span className="text-base-content/40">—</span>}
                </td>
                <td className="font-semibold flex items-center gap-2">
                  {t.type === "entree" ? (
                    <TrendingUp className="text-success w-5 h-5" />
                  ) : (
                    <TrendingDown className="text-error w-5 h-5" />
                  )}
                  <span className={t.type === "entree" ? "text-success" : "text-error"}>
                    {t.type === "entree" ? "+" : "-"}{Number(t.montant).toFixed(2)} FCFA
                  </span>
                </td>
                <td>{formatDate(t.date)}</td>
                <td>
                  <span className={badgeStatut(t.statut)}>
                    {labelStatut(t.statut)}
                  </span>
                </td>
                <td>
                  <button
                    onClick={() => deleteTransaction(t.id)}
                    className="btn btn-sm btn-error btn-soft"
                    title="Supprimer"
                  >
                    <Trash className="w-4 h-4" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ── Modal ajout transaction ── */}
      <dialog id="modal_transaction" className="modal backdrop-blur">
        <div className="modal-box border-2 border-warning/10 border-dashed">
          <form method="dialog">
            <button className="btn btn-sm btn-circle btn-ghost absolute right-2 top-2">✕</button>
          </form>
          <h3 className="font-bold text-lg mb-4">Ajouter une transaction</h3>

          <div className="flex flex-col gap-4">

            {/* Type */}
            <div className="flex flex-col gap-2">
              <label className="label">Type</label>
              <select
                className="select w-full"
                value={form.type}
                onChange={(e) => setForm({ ...form, type: e.target.value, categorie: "" })}
              >
                <option value="entree">Entrée (Revenu)</option>
                <option value="sortie">Sortie (Dépense)</option>
              </select>
            </div>

            {/* Description */}
            <div className="flex flex-col gap-2">
              <label className="label">Description</label>
              <input
                type="text"
                className="input w-full"
                placeholder="Ex: Vente client Alpha SARL"
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
              />
            </div>

            {/* Montant */}
            <div className="flex flex-col gap-2">
              <label className="label">Montant (FCFA)</label>
              <input
                type="number"
                className="input w-full"
                placeholder="Ex: 850000"
                value={form.montant}
                onChange={(e) => setForm({ ...form, montant: e.target.value })}
              />
            </div>

            {/* Catégorie — filtrée selon le type */}
            <div className="flex flex-col gap-2">
              <label className="label">Catégorie</label>
              <select
                className="select w-full"
                value={form.categorie}
                onChange={(e) => setForm({ ...form, categorie: e.target.value })}
              >
                <option value="">-- Choisir une catégorie --</option>
                {categoriesFiltrees.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.nom}
                  </option>
                ))}
              </select>
            </div>

            {/* Date */}
            <div className="flex flex-col gap-2">
              <label className="label">Date</label>
              <input
                type="date"
                className="input w-full"
                value={form.date}
                onChange={(e) => setForm({ ...form, date: e.target.value })}
              />
            </div>

            {/* Statut */}
            <div className="flex flex-col gap-2">
              <label className="label">Statut</label>
              <select
                className="select w-full"
                value={form.statut}
                onChange={(e) => setForm({ ...form, statut: e.target.value })}
              >
                <option value="confirme">Confirmé</option>
                <option value="en_attente">En attente</option>
                <option value="annulé">Annulée</option>
              </select>
            </div>

            {/* Bouton soumettre */}
            <button
              className="w-full btn btn-warning"
              onClick={addTransaction}
              disabled={loading}
            >
              <PlusCircle className="w-4 h-4" />
              {loading ? "Ajout en cours..." : "Ajouter"}
            </button>

          </div>
        </div>
      </dialog>

    </div>
  )
}
